section_css:
/* Meridian — generic test design system. Synthetic; not a real brand. */
:root {
  /* Core palette */
  --brand-core-primary: #0F766E;      /* teal */
  --brand-core-primary-dark: #115E59;
  --brand-core-ink: #111827;          /* headings */
  --brand-core-text: #374151;         /* body */
  --brand-core-muted: #4B5563;        /* captions, footers */
  --brand-core-background: #FFFFFF;
  --brand-core-surface: #F1F5F9;      /* cards */
  --brand-core-border: #E2E8F0;

  /* Accents (charts, highlights) */
  --brand-accents-violet: #6D28D9;
  --brand-accents-amber: #B45309;
  --brand-accents-sky: #0369A1;
  --brand-accents-positive: #15803D;
  --brand-accents-negative: #B91C1C;

  /* Type */
  --font-sans: "Inter", "Helvetica Neue", Arial, sans-serif;
  --fs-eyebrow: 14px;
  --fs-title: 40px;
  --fs-subtitle: 22px;
  --fs-body: 18px;
  --fs-caption: 13px;
  --fs-stat: 56px;

  /* Spacing */
  --space-sm: 12px;
  --space-md: 24px;
  --space-lg: 40px;
  --slide-pad-x: 88px;
  --slide-pad-y: 72px;

  /* Shape */
  --radius-md: 12px;
  --shadow-sm: 0 1px 3px rgba(17, 24, 39, 0.08);
}



.slide {
  position: relative;
  width: 1280px;
  height: 720px;
  box-sizing: border-box;
  padding: var(--slide-pad-y) var(--slide-pad-x);
  background: var(--brand-core-background);
  color: var(--brand-core-text);
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  line-height: 1.5;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}
.slide.cover {
  background: var(--brand-core-primary);
  color: var(--brand-core-background);
  justify-content: center;
}
.slide.cover .slide-title, .slide.cover .slide-subtitle { color: var(--brand-core-background); }
.eyebrow {
  font-size: var(--fs-eyebrow);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--brand-core-primary);
  margin: 0;
}
.slide.cover .eyebrow { color: var(--brand-core-surface); }
.slide-title {
  font-size: var(--fs-title);
  font-weight: 700;
  line-height: 1.15;
  color: var(--brand-core-ink);
  margin: 0;
}
.slide-subtitle {
  font-size: var(--fs-subtitle);
  font-weight: 400;
  color: var(--brand-core-muted);
  margin: 0;
}
.content { flex: 1; min-height: 0; display: flex; flex-direction: column; gap: var(--space-md); }
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-lg); flex: 1; min-height: 0; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-md); }
.card {
  background: var(--brand-core-surface);
  border: 1px solid var(--brand-core-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  padding: var(--space-md);
}
.stat-value {
  font-size: var(--fs-stat);
  font-weight: 700;
  line-height: 1;
  color: var(--brand-core-primary);
}
.stat-label { font-size: var(--fs-caption); color: var(--brand-core-muted); margin-top: var(--space-sm); }
.stat-delta.positive { color: var(--brand-accents-positive); }
.stat-delta.negative { color: var(--brand-accents-negative); }
.bullets { margin: 0; padding-left: 1.2em; }
.bullets li { margin-bottom: var(--space-sm); }
.bullets li::marker { color: var(--brand-core-primary); }
.chart-container { position: relative; height: 320px; }
.callout {
  border-left: 4px solid var(--brand-accents-violet);
  padding: var(--space-sm) var(--space-md);
  background: var(--brand-core-surface);
  color: var(--brand-core-ink);
}
.slide-footer {
  position: absolute;
  left: var(--slide-pad-x);
  right: var(--slide-pad-x);
  bottom: 56px;
  display: flex;
  justify-content: space-between;
  font-size: var(--fs-caption);
  color: var(--brand-core-muted);
}
